Local Open Scope sym_scope.

Definition dagTree (d : nat) : DagNTree :=
  match d with
  | 0%nat => dagTree_0
  | 1%nat => dagTree_1
  | 2%nat => dagTree_2
  | 3%nat => dagTree_3
  | 4%nat => dagTree_4
  | 5%nat => dagTree_5
  | 6%nat => dagTree_6
  | 7%nat => dagTree_7
  | 8%nat => dagTree_8
  | 9%nat => dagTree_9
  | 10%nat => dagTree_10
  | 11%nat => dagTree_11
  | 12%nat => dagTree_12
  | 13%nat => dagTree_13
  | 14%nat => dagTree_14
  | 15%nat => dagTree_15
  | 16%nat => dagTree_16
  | 17%nat => dagTree_17
  | 18%nat => dagTree_18
  | 19%nat => dagTree_19
  | 20%nat => dagTree_20
  | _ => emptyDagTree
  end.

Definition dagGet (d : nat) (id : N) : DagNode :=
  ntree_get (dagTree d) id.

Fixpoint NodeTape (d : nat) (id : N) (sL : side) : Prop :=
  match d with
  | O => id = 0%N /\ LeftWallInv sL
  | S d' =>
    let 'MkDag npar nrev _ _ _ _ := dagGet (S d') id in
    exists sLp, NodeTape d' npar sLp /\ sL = bytesToLeft nrev sLp
  end.

Definition RuleSound (d : nat) : Prop :=
  forall (id : N) (q : Q) (sL sR : side) (idOut : N) (qOut : Q),
    NodeTape d id sL ->
    getRuleSlot (dagGet d id) q = RS idOut qOut ->
    exists sL', NodeTape d idOut sL' /\ (sL <{{q}} sR -->* sL' {{qOut}}> sR).

Lemma ruleSound_zero : RuleSound O.
Proof.
  intros id q sL sR idOut qOut [Hid Hwall] Hsl.
  subst id. simpl in Hsl.
  destruct q; try discriminate.
  inversion Hsl; subst idOut qOut.
  destruct (leftWall_step sL sR Hwall) as [sL' [Hwall' Hrc]].
  exists sL'. split; [split; [reflexivity | exact Hwall'] | exact Hrc].
Qed.
Arguments dagTree : simpl never.
Arguments dagGet : simpl never.

Fixpoint checkRuleLoop (tbl : B8Table) (sliceFuel : nat) (pTree : DagNTree)
    (tgtP : N) (tgtRev : list Byte) (tgtQ : Q)
    (fuel : nat) (curP : N) (side_b : bool) (q : Q)
    (lb : list Byte) (cb : Byte) (rb : list Byte) : bool :=
  match fuel with
  | O => false
  | S fuel' =>
    match simSliceBytes tbl sliceFuel side_b q lb cb rb with
    | SliceRight qOut outRev =>
      qEqb qOut tgtQ && N.eqb curP tgtP && sliceEqb outRev tgtRev
    | SliceLeft qOut outB r' =>
      match getRuleSlot (ntree_get pTree curP) qOut with
      | R0 => false
      | RS nextP nextQ =>
        checkRuleLoop tbl sliceFuel pTree tgtP tgtRev tgtQ fuel' nextP false nextQ [] outB r'
      end
    | _ => false
    end
  end.

Lemma checkRuleLoop_sound sliceFuel d :
  RuleSound d ->
  forall tgtP tgtRev tgtQ fuel curP side_b q lb cb rb (sLp sR : side),
    NodeTape d curP sLp ->
    checkRuleLoop theB8Table sliceFuel (dagTree d) tgtP tgtRev tgtQ fuel curP side_b q lb cb rb = true ->
    exists sLp', NodeTape d tgtP sLp' /\
      (byteEntryCfg side_b q cb (bytesToLeft lb sLp) (bytesToRight rb sR) -->*
       bytesToLeft tgtRev sLp' {{tgtQ}}> sR).
Proof.
  intros HRS tgtP tgtRev tgtQ fuel.
  induction fuel as [|fuel IH]; intros curP side_b q lb cb rb sLp sR Hnt Hchk;
    cbn [checkRuleLoop] in Hchk; [discriminate |].
  pose proof (simSliceBytes_sound sliceFuel side_b q lb cb rb sLp sR) as Hsim.
  destruct (simSliceBytes theB8Table sliceFuel side_b q lb cb rb)
    as [qOut outB r' | qOut outRev | |]; try discriminate.
  - fold (dagGet d curP) in Hchk.
    destruct (getRuleSlot (dagGet d curP) qOut) as [|nextP nextQ] eqn:Hsl; [discriminate |].
    destruct (HRS curP qOut sLp (bytesToRight (outB :: r') sR) nextP nextQ Hnt Hsl)
      as [sLp1 [Hnt1 Hwall]].
    destruct (IH nextP false nextQ [] outB r' sLp1 sR Hnt1 Hchk)
      as [sLp' [Hnt' Hrest]].
    exists sLp'. split; [exact Hnt' |].
    exact (ev_trans _ _ _ Hsim (ev_trans _ _ _ Hwall Hrest)).
  - apply andb_prop in Hchk as [H1 Hs].
    apply andb_prop in H1 as [Hq Hp].
    apply qEqb_eq in Hq. apply N.eqb_eq in Hp. apply sliceEqb_eq in Hs.
    subst qOut curP outRev.
    exists sLp. split; [exact Hnt | exact Hsim].
Qed.
Arguments checkRuleLoop : simpl never.

Definition checkSlot (tbl : B8Table) (sliceFuel loopFuel : nat) (pTree cTree : DagNTree)
    (srcP : N) (srcRev : list Byte) (qin : Q) (sl : RuleSlot) : bool :=
  match sl with
  | R0 => true
  | RS idOut qOut =>
    match srcRev with
    | [] => false
    | cb0 :: lb0 =>
      let 'MkDag tgtP tgtRev _ _ _ _ := ntree_get cTree idOut in
      checkRuleLoop tbl sliceFuel pTree tgtP tgtRev qOut loopFuel srcP true qin lb0 cb0 []
    end
  end.

Definition checkDagNode (tbl : B8Table) (sliceFuel loopFuel : nat) (pTree cTree : DagNTree)
    (dn : DagNode) : bool :=
  let 'MkDag srcP srcRev s0 s1 s4 s5 := dn in
  checkSlot tbl sliceFuel loopFuel pTree cTree srcP srcRev A s0 &&
  checkSlot tbl sliceFuel loopFuel pTree cTree srcP srcRev B s1 &&
  checkSlot tbl sliceFuel loopFuel pTree cTree srcP srcRev E s4 &&
  checkSlot tbl sliceFuel loopFuel pTree cTree srcP srcRev F s5.

Lemma checkSlot_sound sliceFuel loopFuel d :
  RuleSound d ->
  forall id qin idOut qOut srcP srcRev s0 s1 s4 s5 (sL sR : side),
    dagGet (S d) id = MkDag srcP srcRev s0 s1 s4 s5 ->
    NodeTape (S d) id sL ->
    checkSlot theB8Table sliceFuel loopFuel (dagTree d) (dagTree (S d))
      srcP srcRev qin (RS idOut qOut) = true ->
    exists sL', NodeTape (S d) idOut sL' /\ (sL <{{qin}} sR -->* sL' {{qOut}}> sR).
Proof.
  intros HRS id qin idOut qOut srcP srcRev s0 s1 s4 s5 sL sR Hget Hnt Hslot.
  cbn [NodeTape] in Hnt. rewrite Hget in Hnt.
  destruct Hnt as [sLp [HntP ->]].
  cbn [checkSlot] in Hslot.
  destruct srcRev as [|cb0 lb0]; [discriminate |].
  fold (dagGet (S d) idOut) in Hslot.
  destruct (dagGet (S d) idOut) as [tgtP tgtRev t0 t1 t4 t5] eqn:Htgt.
  destruct (checkRuleLoop_sound sliceFuel d HRS tgtP tgtRev qOut loopFuel srcP true qin lb0 cb0 []
              sLp sR HntP Hslot) as [sLp' [HntP' Hrc]].
  exists (bytesToLeft tgtRev sLp').
  split.
  - cbn [NodeTape]. rewrite Htgt. exists sLp'. split; [exact HntP' | reflexivity].
  - exact Hrc.
Qed.

Definition checkLayerTrees (tbl : B8Table) (sliceFuel loopFuel : nat)
    (pTree cTree : DagNTree) : bool :=
  ntree_forall (checkDagNode tbl sliceFuel loopFuel pTree cTree) cTree.

Definition checkLayerAt (tbl : B8Table) (sliceFuel loopFuel d : nat) : bool :=
  checkLayerTrees tbl sliceFuel loopFuel (dagTree d) (dagTree (S d)).

Lemma checkLayer_sound sliceFuel loopFuel d :
  RuleSound d ->
  checkLayerAt theB8Table sliceFuel loopFuel d = true ->
  RuleSound (S d).
Proof.
  intros HRS Htree id q sL sR idOut qOut Hnt Hsl.
  unfold checkLayerAt, checkLayerTrees in Htree.
  assert (Hnode : checkDagNode theB8Table sliceFuel loopFuel (dagTree d) (dagTree (S d))
                    (dagGet (S d) id) = true).
  { unfold dagGet.
     exact (ntree_forall_sound
       (checkDagNode theB8Table sliceFuel loopFuel (dagTree d) (dagTree (S d)))
       (dagTree (S d)) eq_refl Htree id). }
  destruct (dagGet (S d) id) as [srcP srcRev s0 s1 s4 s5] eqn:Hget.
  cbn [checkDagNode] in Hnode.
  apply andb_prop in Hnode as [H124 Hs5].
  apply andb_prop in H124 as [H12 Hs4].
  apply andb_prop in H12 as [Hs0 Hs1].
  cbn [getRuleSlot] in Hsl.
  destruct q; try discriminate.
  - subst s0. exact (checkSlot_sound sliceFuel loopFuel d HRS id A idOut qOut _ _ _ _ _ _ _ _ Hget Hnt Hs0).
  - subst s1. exact (checkSlot_sound sliceFuel loopFuel d HRS id B idOut qOut _ _ _ _ _ _ _ _ Hget Hnt Hs1).
  - subst s4. exact (checkSlot_sound sliceFuel loopFuel d HRS id E idOut qOut _ _ _ _ _ _ _ _ Hget Hnt Hs4).
  - subst s5. exact (checkSlot_sound sliceFuel loopFuel d HRS id F idOut qOut _ _ _ _ _ _ _ _ Hget Hnt Hs5).
Qed.

Fixpoint checkLayersUpTo (tbl : B8Table) (sliceFuel loopFuel n : nat) : bool :=
  match n with
  | O => true
  | S d => checkLayersUpTo tbl sliceFuel loopFuel d && checkLayerAt tbl sliceFuel loopFuel d
  end.

Lemma checkLayersUpTo_sound (sliceFuel loopFuel n : nat) :
  checkLayersUpTo theB8Table sliceFuel loopFuel n = true -> forall d, (d <= n)%nat -> RuleSound d.
Proof.
  induction n as [|n IH]; intros Hchk d Hle.
  - assert (d = O) by lia. subst d. exact ruleSound_zero.
  - cbn [checkLayersUpTo] in Hchk. apply andb_prop in Hchk as [Hprev Hcur].
    destruct (PeanoNat.Nat.eq_dec d (S n)) as [-> | Hneq].
    + exact (checkLayer_sound sliceFuel loopFuel n (IH Hprev n (PeanoNat.Nat.le_refl n)) Hcur).
    + apply IH; [exact Hprev | lia].
Qed.

Lemma dag_valid : checkLayersUpTo theB8Table 50%nat 170%nat 20%nat = true.
Proof. vm_check_eq. Qed.

Lemma dagTree_gt20 (d : nat) : (20 < d)%nat -> dagTree d = emptyDagTree.
Proof.
  intros Hgt. do 21 (destruct d as [|d]; [lia |]). reflexivity.
Qed.

Lemma ruleSound_all (d : nat) : RuleSound d.
Proof.
  destruct (PeanoNat.Nat.le_gt_cases d 20%nat) as [Hle | Hgt].
  - exact (checkLayersUpTo_sound 50%nat 170%nat 20%nat dag_valid d Hle).
  - intros id q sL sR idOut qOut _ Hsl.
    unfold dagGet in Hsl. rewrite (dagTree_gt20 d Hgt) in Hsl.
    destruct id as [|[p|p|]]; simpl in Hsl; destruct q; discriminate.
Qed.

Definition initSliceBytes (d : nat) : list Byte :=
  match d with
  | 0%nat => [h04; h00]
  | 1%nat => [h00; h24]
  | 2%nat => [h64; h02]
  | 3%nat => [h00; h00]
  | 4%nat => [h00; h00]
  | 5%nat => [h00; h00]
  | 6%nat => [h00; h00]
  | 7%nat => [h00; h00]
  | 8%nat => [h00; h00; h00; h00]
  | 9%nat => [h00; h00; h00; h00]
  | 10%nat => [h00; h00]
  | 11%nat => [h00; h00]
  | 12%nat => [h00; h00; h00; h00]
  | 13%nat => [h00; h00]
  | 14%nat => [h00; h00; h00; h00]
  | 15%nat => [h00; h00; h00; h00; h00]
  | 16%nat => [h00; h00; h00]
  | 17%nat => [h00; h00; h00; h00; h00; h00]
  | 18%nat => [h00; h00; h00; h00]
  | 19%nat => [h00; h00; h00; h00]
  | 20%nat => [h00; h00; h00; h00; h00; h00]
  | _ => [h00]
  end.

Definition tailRightFrom (d : nat) : side :=
  match d with
  | 0%nat => bytesToRight [h04; h00] (bytesToRight [h00; h24] (bytesToRight [h64; h02] 0inf))
  | 1%nat => bytesToRight [h00; h24] (bytesToRight [h64; h02] 0inf)
  | 2%nat => bytesToRight [h64; h02] 0inf
  | _ => 0inf
  end.

Lemma zero_cons_0inf : 0 >> 0inf = 0inf.
Proof. symmetry. exact (const_unfold _ 0). Qed.

Lemma bitsToSide_zeros n : bitsToSide (repeat false n) 0inf = 0inf.
Proof.
  induction n as [|n IH]; simpl; [reflexivity | rewrite IH; exact zero_cons_0inf].
Qed.

Lemma byteBitsToSide_zero : byteBitsToSide h00 0inf = 0inf.
Proof. exact (bitsToSide_zeros 8%nat). Qed.

Lemma tailRightFrom_unfold (d : nat) :
  tailRightFrom d = bytesToRight (initSliceBytes d) (tailRightFrom (S d)).
Proof.
  do 21 (destruct d as [|d]; [simpl bytesToRight; repeat rewrite byteBitsToSide_zero; reflexivity |]).
  simpl. rewrite byteBitsToSide_zero. reflexivity.
Qed.

Lemma tail35_eq_tailRightFrom0 :
  bitsToSide tail35 0inf = tailRightFrom 0%nat.
Proof.
  rewrite <- (bitsToSide_zeros 6%nat) at 1.
  rewrite <- bitsToSide_app.
  unfold tailRightFrom, bytesToRight, byteBitsToSide.
  reflexivity.
Qed.

Definition topPushIds : list N := [0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N; 0%N].

Fixpoint simTopLoop (tbl : B8Table) (sliceFuel fuel : nat) (cd : nat) (lid : N) (side_b : bool) (q : Q)
    (cb : Byte) (rb : list Byte) (pushes : list N) : bool :=
  match fuel with
  | O => false
  | S fuel' =>
    match simSliceBytes tbl sliceFuel side_b q [] cb rb with
    | SliceHalt => true
    | SliceLeft qOut outB r' =>
      match getRuleSlot (dagGet cd lid) qOut with
      | R0 => false
      | RS nextId nextQ => simTopLoop tbl sliceFuel fuel' cd nextId false nextQ outB r' pushes
      end
    | SliceRight qOut outRev =>
      match pushes with
      | [] => false
      | nid :: ps' =>
        let cd' := S cd in
        let 'MkDag npar nrev _ _ _ _ := dagGet cd' nid in
        if (N.eqb npar lid && sliceEqb nrev outRev)%bool then
          match initSliceBytes cd' with
          | [] => false
          | nb :: rNext => simTopLoop tbl sliceFuel fuel' cd' nid false qOut nb rNext ps'
          end
        else false
      end
    | SliceFail => false
    end
  end.

Lemma sim_top_valid :
  simTopLoop theB8Table 50%nat (Nat.mul 15 30) 0%nat 0%N false A h04 [h00] topPushIds = true.
Proof. vm_check_eq. Qed.

Lemma simTopLoop_sound sliceFuel fuel cd lid side_b q cb rb pushes (sL : side) :
  NodeTape cd lid sL ->
  simTopLoop theB8Table sliceFuel fuel cd lid side_b q cb rb pushes = true ->
  halts tm (byteEntryCfg side_b q cb sL (bytesToRight rb (tailRightFrom (S cd)))).
Proof.
  revert cd lid side_b q cb rb pushes sL.
  induction fuel as [|fuel IH]; intros cd lid side_b q cb rb pushes sL Hnt Hchk;
    cbn [simTopLoop] in Hchk; [discriminate |].
  pose proof (simSliceBytes_sound sliceFuel side_b q [] cb rb sL (tailRightFrom (S cd))) as Hsim.
  cbn [bytesToLeft] in Hsim.
  destruct (simSliceBytes theB8Table sliceFuel side_b q [] cb rb)
    as [qOut outB r' | qOut outRev | |]; try discriminate.
  - destruct (getRuleSlot (dagGet cd lid) qOut) as [|nextId nextQ] eqn:Hsl; [discriminate |].
    destruct (ruleSound_all cd lid qOut sL (bytesToRight (outB :: r') (tailRightFrom (S cd)))
                nextId nextQ Hnt Hsl) as [sL' [Hnt' Hwall]].
    pose proof (IH cd nextId false nextQ outB r' pushes sL' Hnt' Hchk) as Hih.
    exact (evstep_halts _ _ Hsim (evstep_halts _ _ Hwall Hih)).
  - destruct pushes as [|nid ps']; [discriminate |].
    destruct (dagGet (S cd) nid) as [npar nrev s0 s1 s4 s5] eqn:Hget.
    destruct ((N.eqb npar lid && sliceEqb nrev outRev)%bool) eqn:Heq; [| discriminate].
    apply andb_prop in Heq as [Hp Hs].
    apply N.eqb_eq in Hp. apply sliceEqb_eq in Hs. subst npar nrev.
    assert (Hnt' : NodeTape (S cd) nid (bytesToLeft outRev sL)).
    { cbn [NodeTape]. rewrite Hget. exists sL. split; [exact Hnt | reflexivity]. }
    destruct (initSliceBytes (S cd)) as [|nb rNext] eqn:Hin; [discriminate |].
    pose proof (IH (S cd) nid false qOut nb rNext ps' (bytesToLeft outRev sL) Hnt' Hchk) as Hih.
    apply (evstep_halts _ _ Hsim).
    rewrite (tailRightFrom_unfold (S cd)), Hin.
    exact Hih.
  - exact Hsim.
Qed.
Arguments simTopLoop : simpl never.

Lemma main_halts : halts tm c0.
Proof.
  destruct link3_reaches as [c Hlink3].
  pose proof (ev_trans _ _ _ link1_reaches Hlink3) as Hreach.
  rewrite tail35_eq_tailRightFrom0 in Hreach.
  assert (Hnt0 : NodeTape 0%nat 0%N (bitsToSide (pref35At W0) (crysTape P4 c))).
  { split; [reflexivity | exists W0, c; reflexivity]. }
  pose proof (simTopLoop_sound 50%nat (Nat.mul 15 30) 0%nat 0%N false A h04 [h00] topPushIds
                (bitsToSide (pref35At W0) (crysTape P4 c)) Hnt0 sim_top_valid) as Hhalts.
  exact (evstep_halts _ _ Hreach Hhalts).
Qed.

End M286.

Theorem halt : halts tm c0.
Proof. exact M286.main_halts. Qed.
